import { delete_broadcast_channel } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    delete_broadcast: Boolean,
    dashboarditems: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_event() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(delete_broadcast_channel, {
          input: {
            team_id: this.dashboarditems.team_id,
            user_email_id: this.$store.getters.GetUserObj.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.delete_broadcast_channel);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
